"""Original schematic learning aids generated from local vector geometry."""
import pathlib,json,math
ROOT=pathlib.Path(__file__).resolve().parents[1];P=ROOT/'public/diagrams'
def svg(name,body):
 (P/name).write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 340"><rect width="720" height="340" fill="#f2f6ed"/><g font-family="sans-serif" fill="#214b3e">'+body+'</g></svg>')
body='<text x="24" y="30" font-size="20">Sodium-23: simplified shell-count model</text>'
for radius in [45,85,125]:body+=f'<circle cx="205" cy="185" r="{radius}" fill="none" stroke="#7b9a86"/>'
body+='<circle cx="205" cy="185" r="27" fill="#f1ce7c"/><text x="186" y="181" font-size="13">11 p</text><text x="186" y="198" font-size="13">12 n</text>'
for radius,count in [(45,2),(85,8),(125,1)]:
 for n in range(count):
  angle=n*math.tau/count-math.pi/2;x=205+radius*math.cos(angle);y=185+radius*math.sin(angle);body+=f'<circle cx="{x:.1f}" cy="{y:.1f}" r="7" fill="#20788b"/>'
body+='<text x="390" y="105" font-size="19">Atomic number: 11</text><text x="390" y="145" font-size="19">Mass number: 23</text><text x="390" y="185" font-size="19">Electron count: 2, 8, 1</text><text x="390" y="225" font-size="16">Not a picture of orbital paths.</text>'
svg('sodium.svg',body)
svg('reflection.svg','''<text x="24" y="30" font-size="21">Reflection: angles are measured to the normal</text><path d="M80 270H640" stroke="#64837b" stroke-width="9"/><path d="M360 55V292" stroke="#517b70" stroke-dasharray="8 6"/><path d="M170 80L360 270L550 80" fill="none" stroke="#c27e24" stroke-width="4"/><path d="M260 157L268 178L247 170M450 180L472 172L463 193" fill="#c27e24"/><text x="80" y="95" font-size="17">Incident ray</text><text x="525" y="95" font-size="17">Reflected ray</text><text x="375" y="70" font-size="17">Normal</text><text x="300" y="200" font-size="20">45°</text><text x="385" y="200" font-size="20">45°</text><text x="275" y="320" font-size="19">Plane mirror</text>''')
svg('photosynthesis.svg','''<text x="24" y="30" font-size="21">Photosynthesis: inputs and products</text><ellipse cx="370" cy="170" rx="105" ry="65" fill="#b2d790" stroke="#487847" stroke-width="3"/><text x="313" y="164" font-size="19">Green leaf</text><text x="306" y="188" font-size="15">chloroplasts</text><g stroke="#a9862d" stroke-width="4"><path d="M370 60V98M360 88L370 100L380 88"/></g><text x="325" y="57" font-size="17">Light energy</text><g stroke="#447c88" stroke-width="3"><path d="M55 125H252M240 115L254 125L240 135M55 218H252M240 208L254 218L240 228M483 125H663M651 115L665 125L651 135M483 218H663M651 208L665 218L651 228" fill="none"/></g><text x="55" y="109" font-size="18">Carbon dioxide</text><text x="70" y="200" font-size="18">Water</text><text x="532" y="109" font-size="18">Oxygen</text><text x="532" y="200" font-size="18">Glucose</text><text x="100" y="295" font-size="17">Food made by photosynthesis can be used or stored.</text>''')
svg('earth-layers.svg','''<text x="24" y="30" font-size="21">Earth’s internal layers (not to scale)</text><circle cx="225" cy="185" r="125" fill="#706b4b"/><circle cx="225" cy="185" r="116" fill="#b78350"/><circle cx="225" cy="185" r="70" fill="#e0a450"/><circle cx="225" cy="185" r="34" fill="#f8d980"/><g stroke="#214b3e" stroke-width="2" fill="none"><path d="M340 145L440 80"/><path d="M310 205L440 145"/><path d="M278 210L440 215"/><path d="M225 185L440 280"/></g><g font-size="19"><text x="455" y="85">Crust</text><text x="455" y="150">Mantle (mainly solid)</text><text x="455" y="220">Liquid outer core</text><text x="455" y="285">Solid inner core</text></g>''')
updates={'chemistry-f2-atoms':('sodium.svg','Sodium-23 shell-count model: 11 protons, 12 neutrons and electron arrangement 2,8,1.'),'physics-f2-light':('reflection.svg','Incident and reflected rays make equal 45-degree angles with the normal to a plane mirror.'),'biology-f1-photosynthesis':('photosynthesis.svg','Light-driven photosynthesis uses carbon dioxide and water to produce glucose and oxygen.'),'geography-f2-earth-systems':('earth-layers.svg','Schematic crust, mantle, liquid outer core and solid inner core, not to scale.')}
p=ROOT/'content/library.json';d=json.loads(p.read_text())
for l in d['lessons']:
 if l['id'] in updates:name,alt=updates[l['id']];l.update(diagram='/diagrams/'+name,diagramAlt=alt)
p.write_text(json.dumps(d,ensure_ascii=False,indent=2))
